// گرفتن تمام دیتاهای ورودی از نود Merge
let allData = $input.all();

// ۱. دریافت اطلاعات ۴ تصویر به ترتیب (ایندکس ۰ تا ۳)
let featureImageId = allData[0].json.id; 
let img1Url = allData[1].json.source_url;
let img2Url = allData[2].json.source_url;
let img3Url = allData[3].json.source_url;

// ۲. دریافت متن مقاله از آیتم پنجم (ایندکس ۴)
let rawOutput = allData[4].json.output;
let parsedArticle = JSON.parse(rawOutput);
let articleHtml = parsedArticle.article_html_content;
let articleTitle = parsedArticle.article_title;

// ۳. ساخت تگ‌های HTML با لینک‌های واقعی و استایل ریسپانسیو
let imgTag1 = `<img src="${img1Url}" alt="تصویر مرتبط با مقاله" style="width:100%; height:auto; border-radius:10px; margin:25px 0; box-shadow: 0 4px 8px rgba(0,0,0,0.1);">`;
let imgTag2 = `<img src="${img2Url}" alt="ادامه مقاله" style="width:100%; height:auto; border-radius:10px; margin:25px 0; box-shadow: 0 4px 8px rgba(0,0,0,0.1);">`;
let imgTag3 = `<img src="${img3Url}" alt="بخش پایانی مقاله" style="width:100%; height:auto; border-radius:10px; margin:25px 0; box-shadow: 0 4px 8px rgba(0,0,0,0.1);">`;

// --- ۴. عملیات جاگذاری تصاویر در متن ---

// جاگذاری تصویر اول: دقیقاً بعد از اولین پاراگراف
articleHtml = articleHtml.replace('</p>', '</p>\n' + imgTag1);

// جاگذاری تصویر سوم: دقیقاً قبل از پاراگراف آخر
let lastPIndex = articleHtml.lastIndexOf('<p>');
if (lastPIndex !== -1) {
    articleHtml = articleHtml.substring(0, lastPIndex) + imgTag3 + '\n' + articleHtml.substring(lastPIndex);
}

// جاگذاری تصویر دوم: دقیقاً قبل از هدینگ میانی
let h2Parts = articleHtml.split('<h2>');
if (h2Parts.length > 2) {
    let middleIndex = Math.floor(h2Parts.length / 2);
    let beforeMiddle = h2Parts.slice(0, middleIndex).join('<h2>');
    let afterMiddle = h2Parts.slice(middleIndex).join('<h2>');
    articleHtml = beforeMiddle + imgTag2 + '\n<h2>' + afterMiddle;
}

// ۵. خروجی نهایی، آماده برای نود وردپرس
return {
    json: {
        title: articleTitle,
        content: articleHtml,
        featured_media: featureImageId,
        status: "draft" 
    }
};

return $input.all().map(item => {
  // گرفتن دیتای متنی و شلوغ از فیلد output
  let rawTextData = item.json.output;

  try {
    // تبدیل متن به یک ساختار تمیز و واقعی JSON
    let cleanJsonData = JSON.parse(rawTextData);

    // جایگزین کردن دیتای خروجی با دیتای مرتب‌شده
    return { json: cleanJsonData };

  } catch (error) {
    // در صورتی که ساختار خروجی ایجنت مشکل داشته باشد
    return { 
      json: { 
        error: "خطا در تبدیل متن به JSON", 
        details: error.message,
        original_data: rawTextData
      } 
    };
  }
});

